@startuml
class Driver {
  + driverID : int
  + name : string
  + isOnSickLeave : boolean
}

class Bus {
  + licensePlate : string
  + isInRepairShop : boolean
}

class Route {
  + routeNumber : int
}

class Shift {
  + shiftType : ShiftType
}

enum ShiftType {
  Morning
  Afternoon
  Night
}

class Schedule {
  + date : date
}

Driver "1" -- "*" Schedule
Bus "1" -- "*" Schedule
Route "1" -- "*" Schedule
Schedule "*" -- "1" Shift
Schedule "*" -- "1" Driver
Schedule "*" -- "1" Bus
Schedule "*" -- "1" Route

class CityStaff {}

CityStaff "1" -- "*" Schedule : assigns

@enduml

